do $$ declare r record; begin for r in select jobid from cron.job where jobname in ('page-ready-auto','reply-email-auto','research-nurture-daily','share-to-facebook','system-watchman-weekly','wa-daily-digest','wa-raziel','gsc-daily-sync','gallery-thumbs','post-thumbs','channel-thumbs','wa-channel-ingest','wa-uriel','wa-hatishbi','wa-mora','lab-reflect','research-extract-scan','welcome-auto-new') loop perform cron.unschedule(r.jobid); end loop; end $$;
select cron.schedule('page-ready-auto','*/15 * * * *',$cron$ with s as (select decrypted_secret as key from vault.decrypted_secrets where name='FB_ADMIN_KEY' order by created_at desc limit 1) select net.http_post(url:='https://linswmnnkjxvweumprav.supabase.co/functions/v1/notify-page-ready?mode=send&max=100',headers:=jsonb_build_object('Content-Type','application/json','x-fb-admin-key',s.key),body:='{}'::jsonb) from s where nullif(s.key,'') is not null; $cron$);
